using System;using System.Reflection;using FpsManager;using UnityEngine;
public static class HumanMatchChecks {public static void Run(){var g=new GameObject("Full HS map").AddComponent<Prototype>();g.Initialize();typeof(Prototype).GetMethod("ActivateMatchMap",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(g,new object[]{"de_vertigo"});g.StartMatch();int round=0;for(int n=0;n<50000&&g.Stage!=MatchStage.Finished;n++){g.AdvanceFrame(.05f);if(g.Stage==MatchStage.Timeout)g.ResumeTimeout();if(g.CompletedRounds!=round){round=g.CompletedRounds;Console.WriteLine("ROUND "+round+" SCORE "+g.RoundWins(0)+":"+g.RoundWins(1));Console.Out.Flush();}}int k=0,h=0;for(int i=0;i<10;i++){var s=g.Statistics.Result(i);k+=s.kills;h+=s.headshots;Console.WriteLine(g.Data.players[i].handle+" kills="+s.kills+" hs="+s.headshots+" hs%="+s.HeadshotPercent.ToString("F1"));}Console.WriteLine("FULL_MAP_HS stage="+g.Stage+" rounds="+g.CompletedRounds+" kills="+k+" headkills="+h+" hs%="+(k>0?100f*h/k:0));if(g.Stage!=MatchStage.Finished||k<30||h==k)throw new Exception("full map validation incomplete");}}
